// ── REFINANCE CALCULATOR ────────────────────────────────────
function RefinanceCalc({ onProgress }) {
  const [f, setF] = useState({ balance: "", currentRate: "", currentPayment: "", newRate: "", term: "30", closingCosts: "" });
  const [result, setResult] = useState(null);

  function calc() {
    const balance = parseFloat(f.balance) || 0;
    const newRate = (parseFloat(f.newRate) || 6.5) / 100 / 12;
    const n = parseInt(f.term) * 12;
    const newPayment = balance * (newRate * Math.pow(1 + newRate, n)) / (Math.pow(1 + newRate, n) - 1);
    const currentPmt = parseFloat(f.currentPayment) || 0;
    const savings = currentPmt - newPayment;
    const closing = parseFloat(f.closingCosts) || 0;
    const breakeven = savings > 0 ? Math.ceil(closing / savings) : 0;
    setResult({ newPayment: Math.round(newPayment), savings: Math.round(savings), breakeven });
    onProgress("Refinance Calculator");
  }

  return (
    <div>
      <h2 style={S.h2}>Refinance Calculator</h2>
      <div style={{ background: "#e8f4fd", border: "1px solid #bee3f8", borderRadius: 6, padding: "12px 16px", marginBottom: 20, fontSize: 14 }}>
        💰 <strong>Closing Cost Assistance Available.</strong>{" "}
        <a href="https://myuhm.uhm.com/homehub/signup/yozoude@uhm.com?from_mobile_share=true" target="_blank" rel="noreferrer" style={{ color: C.navy, fontWeight: "bold" }}>Here</a>
      </div>
      <div style={S.card}>
        <div style={S.grid(2)}>
          {[["Current Loan Balance","balance","$250,000"],["Current Interest Rate (%)","currentRate","7.5"],["Current Monthly Payment","currentPayment","$1,750"],["New Interest Rate (%)","newRate","6.25"],["Estimated Closing Costs","closingCosts","$4,000"]].map(([label,key,ph]) => (
            <div key={key}><label style={S.label}>{label}</label><input style={S.input} type="number" placeholder={ph} value={f[key]} onChange={e => setF({...f, [key]: e.target.value})} /></div>
          ))}
          <div>
            <label style={S.label}>New Loan Term</label>
            <select style={S.input} value={f.term} onChange={e => setF({...f, term: e.target.value})}>
              <option value="30">30 Years</option><option value="20">20 Years</option><option value="15">15 Years</option>
            </select>
          </div>
        </div>
        <button style={S.btnPrimary} onClick={calc}>Calculate Savings</button>
      </div>
      {result && (
        <div style={{ ...S.card, background: C.navy }}>
          <div style={S.grid(3)}>
            {[["New Monthly Payment", `$${result.newPayment.toLocaleString()}`], ["Monthly Savings", result.savings > 0 ? `$${result.savings.toLocaleString()}` : "-"], ["Break-Even", result.breakeven > 0 ? `${result.breakeven} months` : "-"]].map(([l, v]) => (
              <div key={l} style={{ textAlign: "center" }}>
                <div style={{ fontSize: 26, fontWeight: "bold", color: C.gold, fontFamily: "Georgia, serif" }}>{v}</div>
                <div style={{ fontSize: 12, color: "rgba(255,255,255,0.7)", marginTop: 4 }}>{l}</div>
              </div>
            ))}
          </div>
          {result.savings > 0 && <p style={{ color: "rgba(255,255,255,0.7)", fontSize: 13, textAlign: "center", marginTop: 12 }}>You'd save ${result.savings}/month. After {result.breakeven} months the refinance pays for itself.</p>}
          <div style={{ textAlign: "center", marginTop: 16 }}>
            <a href={APP_LINK} target="_blank" rel="noreferrer" style={{ ...S.btnGold, textDecoration: "none" }}>Start Your Refinance Application →</a>
          </div>
        </div>
      )}
    </div>
  );
}

