// ── CASH TO CLOSE ───────────────────────────────────────────
const SELLER_LIMITS = {
  conventional: { "under5": 0.03, "5to10": 0.06, "10to25": 0.06, "over25": 0.09 },
  fha: { any: 0.06 },
  va: { any: null },
  usda: { any: 0.06 },
};

function CashToCloseCalc({ onProgress }) {
  const [f, setF] = useState({ price: "", downType: "pct", downPct: "", downAmt: "", closing: "", credits: "", earnest: "", loanType: "conventional" });
  const [result, setResult] = useState(null);

  function calc() {
    const price = parseFloat(f.price) || 0;
    let downAmt = 0;
    if (f.downType === "pct") downAmt = price * ((parseFloat(f.downPct) || 0) / 100);
    else downAmt = parseFloat(f.downAmt) || 0;
    const downPct = price > 0 ? (downAmt / price) * 100 : 0;
    const closing = parseFloat(f.closing) || Math.round(price * 0.018);
    const credits = parseFloat(f.credits) || 0;
    const earnest = parseFloat(f.earnest) || 0;
    const total = Math.max(0, downAmt + closing - credits - earnest);

    let sellerLimit = null;
    if (f.loanType === "fha") sellerLimit = price * 0.06;
    else if (f.loanType === "va") sellerLimit = price * 0.04;
    else if (f.loanType === "usda") sellerLimit = price * 0.06;
    else {
      if (downPct < 5) sellerLimit = price * 0.03;
      else if (downPct < 10) sellerLimit = price * 0.06;
      else if (downPct < 25) sellerLimit = price * 0.06;
      else sellerLimit = price * 0.09;
    }

    setResult({ total, downAmt: Math.round(downAmt), closing, credits, earnest, sellerLimit: Math.round(sellerLimit), downPct: Math.round(downPct * 10) / 10 });
    onProgress("Cash-to-Close Calculator");
  }

  const loanLabels = { conventional: "Conventional", fha: "FHA", va: "VA", usda: "USDA" };
  const sellerLimitNote = { conventional: "Fannie Mae / Freddie Mac guidelines", fha: "HUD guidelines", va: "VA guidelines", usda: "USDA guidelines" };

  return (
    <div>
      <h2 style={S.h2}>Cash-to-Close Calculator</h2>
      <div style={S.card}>
        <label style={S.label}>Loan Type</label>
        <div style={{ display: "flex", gap: 10, marginBottom: 16, flexWrap: "wrap" }}>
          {Object.entries(loanLabels).map(([val, label]) => (
            <button key={val} onClick={() => setF({...f, loanType: val})} style={{ padding: "8px 18px", borderRadius: 4, border: `1.5px solid ${f.loanType === val ? C.navy : C.border}`, background: f.loanType === val ? C.navy : C.white, color: f.loanType === val ? C.white : C.muted, fontSize: 13, cursor: "pointer" }}>{label}</button>
          ))}
        </div>
        <label style={S.label}>Purchase Price</label>
        <input style={S.input} type="number" placeholder="$300,000" value={f.price} onChange={e => setF({...f, price: e.target.value})} />
        <label style={S.label}>Down Payment - Express as:</label>
        <div style={{ display: "flex", gap: 10, marginBottom: 12 }}>
          <button onClick={() => setF({...f, downType: "pct"})} style={{ padding: "6px 16px", borderRadius: 4, border: `1.5px solid ${f.downType === "pct" ? C.navy : C.border}`, background: f.downType === "pct" ? C.navy : C.white, color: f.downType === "pct" ? C.white : C.muted, fontSize: 13, cursor: "pointer" }}>Percentage</button>
          <button onClick={() => setF({...f, downType: "amt"})} style={{ padding: "6px 16px", borderRadius: 4, border: `1.5px solid ${f.downType === "amt" ? C.navy : C.border}`, background: f.downType === "amt" ? C.navy : C.white, color: f.downType === "amt" ? C.white : C.muted, fontSize: 13, cursor: "pointer" }}>Dollar Amount</button>
        </div>
        {f.downType === "pct" ? (
          <input style={S.input} type="number" placeholder="e.g. 10" value={f.downPct} onChange={e => setF({...f, downPct: e.target.value})} />
        ) : (
          <input style={S.input} type="number" placeholder="e.g. $30,000" value={f.downAmt} onChange={e => setF({...f, downAmt: e.target.value})} />
        )}
        <div style={S.grid(3)}>
          {[["Est. Closing Costs (or leave blank)", "closing", "Auto-calculated"], ["Seller Credits", "credits", "$0"], ["Earnest Money Paid", "earnest", "$2,000"]].map(([l, k, ph]) => (
            <div key={k}><label style={S.label}>{l}</label><input style={S.input} type="number" placeholder={ph} value={f[k]} onChange={e => setF({...f, [k]: e.target.value})} /></div>
          ))}
        </div>
        <button style={S.btnPrimary} onClick={calc}>Calculate Cash to Close</button>
      </div>
      {result && (
        <div>
          <div style={{ ...S.card, background: C.navy, textAlign: "center" }}>
            <div style={{ fontSize: 13, color: "rgba(255,255,255,0.6)", marginBottom: 6 }}>Total Cash Needed at Closing</div>
            <div style={{ fontSize: 48, fontWeight: "bold", color: C.gold, fontFamily: "Georgia, serif" }}>${result.total.toLocaleString()}</div>
            <div style={{ display: "flex", justifyContent: "center", gap: 28, marginTop: 20, fontSize: 13, flexWrap: "wrap" }}>
              {[["Down Payment ({pct}%)", `+$${result.downAmt.toLocaleString()}`], ["Closing Costs", `+$${result.closing.toLocaleString()}`], ["Seller Credits", `-$${result.credits.toLocaleString()}`], ["Earnest Money", `-$${result.earnest.toLocaleString()}`]].map(([l, v]) => (
                <div key={l} style={{ textAlign: "center" }}>
                  <div style={{ color: C.gold }}>{v}</div>
                  <div style={{ color: "rgba(255,255,255,0.5)", fontSize: 11 }}>{l.replace("{pct}", result.downPct)}</div>
                </div>
              ))}
            </div>
          </div>
          <div style={{ ...S.card, background: C.offwhite }}>
            <h3 style={S.h3}>Seller Concession Limit - {loanLabels[f.loanType]}</h3>
            <p style={{ fontSize: 14, color: C.muted, marginTop: -8 }}>{sellerLimitNote[f.loanType]}</p>
            <div style={{ fontSize: 22, fontWeight: "bold", color: C.navy, fontFamily: "Georgia, serif" }}>${result.sellerLimit.toLocaleString()}</div>
            <p style={{ fontSize: 13, color: C.muted, marginTop: 4 }}>Maximum seller concessions allowed based on your loan type and {result.downPct}% down payment. Your advisor can help negotiate this into your offer.</p>
            <a href={APP_LINK} target="_blank" rel="noreferrer" style={{ ...S.btnGold, textDecoration: "none", display: "inline-block", marginTop: 8 }}>Apply Now →</a>
          </div>
        </div>
      )}
    </div>
  );
}


// ── CREDIT PLANNER ──────────────────────────────────────────
const CREDIT_ITEMS = [
  { task: "Get free credit reports from AnnualCreditReport.com", impact: "High", time: "Today" },
  { task: "Dispute any errors or inaccuracies on your report", impact: "High", time: "1-2 weeks" },
  { task: "Pay down credit cards below 30% utilization", impact: "High", time: "1-3 months" },
  { task: "Set up automatic payments to avoid late payments", impact: "High", time: "This week" },
  { task: "Avoid opening new credit accounts", impact: "Medium", time: "Ongoing" },
  { task: "Keep old accounts open to maintain history length", impact: "Medium", time: "Ongoing" },
  { task: "Request a credit limit increase on existing cards", impact: "Medium", time: "1 month" },
  { task: "Pay down installment loans (student, auto)", impact: "Medium", time: "Ongoing" },
  { task: "Become an authorized user on a responsible account", impact: "Medium", time: "1 month" },
  { task: "Monitor your score monthly for changes", impact: "Low", time: "Monthly" },
];

function CreditPlanner({ onProgress }) {
  const [contact, setContact] = useState({ name: "", email: "" });
  const [score, setScore] = useState("");
  const [target, setTarget] = useState("");
  const [checked, setChecked] = useState({});
  const [showResult, setShowResult] = useState(false);

  const done = Object.values(checked).filter(Boolean).length;
  const impactColor = { High: C.green, Medium: C.gold, Low: C.muted };

  function finish() {
    setShowResult(true);
    onProgress("Credit Planner");
    const completedItems = CREDIT_ITEMS.filter((_, i) => checked[i]);
    const rows = [
      ["Current Credit Score", score],
      ["Target Credit Score", target],
      ["Points to Improve", `${Math.max(0, parseInt(target) - parseInt(score))}`],
      ["Checklist Items Completed", `${done} / ${CREDIT_ITEMS.length}`],
      ...completedItems.map(item => [`✓ ${item.task}`, item.impact + " Impact"]),
    ];
    generatePDF(`Credit Improvement Plan - ${contact.name}`, rows, { name: contact.name, email: contact.email }, `Your advisor can review this plan with you and suggest lender-specific strategies. ${APP_LINK}`);
  }

  return (
    <div>
      <h2 style={S.h2}>Credit Improvement Planner</h2>
      <div style={S.card}>
        <h3 style={S.h3}>Your Info (for PDF report)</h3>
        <div style={S.grid(2)}>
          <div><label style={S.label}>Full Name</label><input style={S.input} value={contact.name} onChange={e => setContact({...contact, name: e.target.value})} /></div>
          <div><label style={S.label}>Email</label><input style={S.input} type="email" value={contact.email} onChange={e => setContact({...contact, email: e.target.value})} /></div>
          <div><label style={S.label}>Current Credit Score</label><input style={S.input} type="number" placeholder="e.g. 640" value={score} onChange={e => setScore(e.target.value)} /></div>
          <div><label style={S.label}>Target Credit Score</label><input style={S.input} type="number" placeholder="e.g. 720" value={target} onChange={e => setTarget(e.target.value)} /></div>
        </div>
        {score && target && parseInt(target) > parseInt(score) && (
          <div style={{ background: C.navy, color: C.white, borderRadius: 6, padding: "12px 16px", fontSize: 14 }}>
            You need to improve by <strong style={{ color: C.gold }}>{parseInt(target) - parseInt(score)} points</strong>. Complete the checklist below.
          </div>
        )}
      </div>
      <div style={S.card}>
        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 16 }}>
          <h3 style={{ ...S.h3, marginBottom: 0 }}>Action Checklist</h3>
          <span style={{ fontSize: 13, color: C.muted }}>{done}/{CREDIT_ITEMS.length} complete</span>
        </div>
        <div style={{ background: C.light, borderRadius: 20, height: 8, marginBottom: 16, overflow: "hidden" }}>
          <div style={S.progressBar((done / CREDIT_ITEMS.length) * 100, C.navy)} />
        </div>
        {CREDIT_ITEMS.map((item, i) => (
          <label key={i} style={{ display: "flex", alignItems: "flex-start", gap: 12, padding: "10px 0", borderBottom: `1px solid ${C.light}`, cursor: "pointer" }}>
            <input type="checkbox" checked={!!checked[i]} onChange={() => setChecked({...checked, [i]: !checked[i]})} style={{ marginTop: 2, accentColor: C.navy }} />
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: 14, color: checked[i] ? C.muted : C.navy, textDecoration: checked[i] ? "line-through" : "none" }}>{item.task}</div>
              <div style={{ fontSize: 12, marginTop: 3 }}>
                <span style={S.pill(impactColor[item.impact])}>{item.impact} Impact</span>
                <span style={{ color: C.muted, marginLeft: 8 }}>{item.time}</span>
              </div>
            </div>
          </label>
        ))}
        <div style={{ marginTop: 20, display: "flex", gap: 12, flexWrap: "wrap" }}>
          <button style={S.btnPrimary} onClick={finish}>Download My Credit Plan PDF</button>
        </div>
      </div>
      {showResult && (
        <div style={{ ...S.card, background: C.navy, textAlign: "center", padding: "32px 24px" }}>
          <div style={{ fontSize: 15, color: "rgba(255,255,255,0.8)", marginBottom: 16 }}>Your credit plan PDF has been downloaded. The next step is your mortgage application.</div>
          <a href={APP_LINK} target="_blank" rel="noreferrer" style={{ ...S.btnGold, textDecoration: "none", fontSize: 15, padding: "12px 28px" }}>Start Your Application Now →</a>
        </div>
      )}
    </div>
  );
}

// ── SAVINGS TRACKER ─────────────────────────────────────────
function SavingsTracker({ onProgress }) {
  const [goal, setGoal] = useState("");
  const [saved, setSaved] = useState("");
  const [monthly, setMonthly] = useState("");
  const [expenses, setExpenses] = useState([{ name: "", amount: "" }]);
  const [result, setResult] = useState(null);
  const [expResult, setExpResult] = useState(null);

  function calc() {
    const g = parseFloat(goal) || 0;
    const s = parseFloat(saved) || 0;
    const m = parseFloat(monthly) || 0;
    const remaining = Math.max(0, g - s);
    const months = m > 0 ? Math.ceil(remaining / m) : 0;
    const pct = g > 0 ? Math.min(100, Math.round((s / g) * 100)) : 0;
    const targetDate = months > 0 ? new Date(Date.now() + months * 30 * 24 * 60 * 60 * 1000).toLocaleDateString("en-US", { month: "long", year: "numeric" }) : "Now!";
    setResult({ remaining, months, pct, targetDate, monthly: m, goal: g, saved: s });
    onProgress("Savings Tracker");
  }

  function calcExpenses() {
    const totalCut = expenses.reduce((s, e) => s + (parseFloat(e.amount) || 0), 0);
    setExpResult({
      monthly: totalCut,
      threeMonth: totalCut * 3,
      sixMonth: totalCut * 6,
      annual: totalCut * 12,
    });
  }

  function addExpense() { setExpenses([...expenses, { name: "", amount: "" }]); }
  function updateExpense(i, key, val) { const e = [...expenses]; e[i][key] = val; setExpenses(e); }
  function removeExpense(i) { setExpenses(expenses.filter((_, idx) => idx !== i)); }

  return (
    <div>
      <h2 style={S.h2}>Savings Goal Tracker</h2>
      <div style={S.card}>
        <div style={S.grid(3)}>
          <div><label style={S.label}>Down Payment Goal</label><input style={S.input} type="number" placeholder="$20,000" value={goal} onChange={e => setGoal(e.target.value)} /></div>
          <div><label style={S.label}>Amount Already Saved</label><input style={S.input} type="number" placeholder="$5,000" value={saved} onChange={e => setSaved(e.target.value)} /></div>
          <div><label style={S.label}>Monthly Savings Amount</label><input style={S.input} type="number" placeholder="$500" value={monthly} onChange={e => setMonthly(e.target.value)} /></div>
        </div>
        <button style={S.btnPrimary} onClick={calc}>Track My Progress</button>
      </div>

      {result && (
        <div style={S.card}>
          <div style={{ marginBottom: 16 }}>
            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 8, fontSize: 14 }}>
              <span style={{ color: C.muted }}>Progress toward goal</span>
              <span style={{ fontWeight: "bold", color: C.navy }}>{result.pct}% complete</span>
            </div>
            <div style={{ background: C.light, borderRadius: 20, height: 14, overflow: "hidden" }}>
              <div style={{ width: `${result.pct}%`, height: "100%", background: `linear-gradient(90deg, ${C.navy}, ${C.gold})`, borderRadius: 20, transition: "width 0.6s" }} />
            </div>
          </div>
          <div style={S.grid(4)}>
            {[
              { label: "Goal", val: `$${result.goal.toLocaleString()}`, color: C.navy },
              { label: "Saved", val: `$${result.saved.toLocaleString()}`, color: C.green },
              { label: "Still Needed", val: `$${result.remaining.toLocaleString()}`, color: C.red },
              { label: "Est. Date", val: result.targetDate, color: C.gold },
            ].map(item => (
              <div key={item.label} style={{ textAlign: "center" }}>
                <div style={{ fontSize: 20, fontWeight: "bold", color: item.color, fontFamily: "Georgia, serif" }}>{item.val}</div>
                <div style={{ fontSize: 12, color: C.muted, marginTop: 4 }}>{item.label}</div>
              </div>
            ))}
          </div>
          {result.months > 0 && (
            <div style={{ background: C.offwhite, borderRadius: 6, padding: "14px 18px", marginTop: 16, fontSize: 14, color: C.navy }}>
              💪 <strong>You're making real progress.</strong> At ${result.monthly.toLocaleString()}/month, you'll reach your goal of ${result.goal.toLocaleString()} by <strong>{result.targetDate}</strong> - just {result.months} months away. Every dollar saved is a dollar closer to your front door.
            </div>
          )}
        </div>
      )}

      {/* Expense Removal Simulator */}
      <div style={S.card}>
        <h3 style={S.h3}>💡 What If I Cut These Expenses?</h3>
        <p style={{ fontSize: 13, color: C.muted, marginTop: -8, marginBottom: 16 }}>Add expenses you're considering cutting. See how much you'd save - and how much faster you'd reach your goal.</p>
        {expenses.map((exp, i) => (
          <div key={i} style={{ display: "flex", gap: 10, marginBottom: 10, alignItems: "center" }}>
            <input style={{ ...S.input, marginBottom: 0, flex: 2 }} placeholder="Expense name (e.g. Streaming services)" value={exp.name} onChange={e => updateExpense(i, "name", e.target.value)} />
            <input style={{ ...S.input, marginBottom: 0, flex: 1 }} type="number" placeholder="$/month" value={exp.amount} onChange={e => updateExpense(i, "amount", e.target.value)} />
            {expenses.length > 1 && <button onClick={() => removeExpense(i)} style={{ background: "none", border: "none", color: C.red, cursor: "pointer", fontSize: 18, padding: "0 8px" }}>×</button>}
          </div>
        ))}
        <div style={{ display: "flex", gap: 10, marginTop: 4 }}>
          <button onClick={addExpense} style={{ ...S.btnPrimary, background: "transparent", color: C.navy, border: `1.5px solid ${C.navy}`, fontSize: 13, padding: "8px 16px" }}>+ Add Another</button>
          <button onClick={calcExpenses} style={S.btnGold}>Calculate Savings Impact</button>
        </div>
        {expResult && (
          <div style={{ marginTop: 20, background: C.offwhite, borderRadius: 8, padding: 20 }}>
            <div style={{ fontWeight: "bold", color: C.navy, marginBottom: 16, fontSize: 15 }}>If you cut these expenses, here's what you'd save:</div>
            <div style={S.grid(4)}>
              {[
                { label: "Per Month", val: `$${expResult.monthly.toLocaleString()}` },
                { label: "In 3 Months", val: `$${expResult.threeMonth.toLocaleString()}` },
                { label: "In 6 Months", val: `$${expResult.sixMonth.toLocaleString()}` },
                { label: "In a Year", val: `$${expResult.annual.toLocaleString()}` },
              ].map(item => (
                <div key={item.label} style={{ textAlign: "center", background: C.white, borderRadius: 8, padding: "16px 12px", border: `1px solid ${C.border}` }}>
                  <div style={{ fontSize: 22, fontWeight: "bold", color: C.green, fontFamily: "Georgia, serif" }}>{item.val}</div>
                  <div style={{ fontSize: 12, color: C.muted, marginTop: 4 }}>{item.label}</div>
                </div>
              ))}
            </div>
            {result && expResult.annual > 0 && (
              <div style={{ marginTop: 16, background: C.navy, color: C.white, borderRadius: 6, padding: "14px 18px", fontSize: 14 }}>
                🏠 <strong style={{ color: C.gold }}>Combined with your current savings:</strong> Adding ${expResult.monthly.toLocaleString()}/month to your current ${result.monthly.toLocaleString()}/month means you'd save ${(result.monthly + expResult.monthly).toLocaleString()}/month - reaching your goal {Math.floor(result.remaining / (result.monthly + expResult.monthly))} months sooner.
              </div>
            )}
            <div style={{ marginTop: 12, fontSize: 13, color: C.muted, fontStyle: "italic" }}>Small changes today build your future home. You're closer than you think.</div>
          </div>
        )}
      </div>
    </div>
  );
}


