const ARTICLES = [
  { cat: "Homebuying Basics", title: "The 7 Steps to Buying Your First Home", read: "8 min", content: `Buying a home is one of the most significant financial decisions you'll ever make. Understanding the full process from start to finish helps you feel confident and in control.\n\n**Step 1: Check Your Financial Health**\nBefore anything else, review your credit score, calculate your debt-to-income ratio, and assess your savings. Lenders will look at all three. A credit score of 620+ qualifies for most conventional loans; 580+ for FHA.\n\n**Step 2: Get Pre-Approved**\nA mortgage pre-approval tells you exactly how much house you can afford and shows sellers you're serious. You'll need pay stubs, tax returns, bank statements, and ID.\n\n**Step 3: Find a Real Estate Agent**\nA buyer's agent represents your interests at no cost to you - they're compensated from the seller's proceeds. Interview at least two agents before committing.\n\n**Step 4: Search for Homes**\nDefine your must-haves vs. nice-to-haves before you start touring. Location, school district, commute, and long-term resale value are often more important than finishes you can change.\n\n**Step 5: Make an Offer**\nYour agent will help you craft a competitive offer based on comparable sales. Earnest money (typically 1-2% of the purchase price) is submitted with the offer.\n\n**Step 6: Inspections and Appraisal**\nAlways get a home inspection. Your lender will also order an appraisal to confirm the home's value supports the loan amount. Negotiate repairs or credits based on inspection findings.\n\n**Step 7: Close**\nClosing day involves signing a significant amount of paperwork and transferring funds. You'll receive the keys once the deed is recorded. Congratulations - you're a homeowner.` },
  { cat: "Homebuying Basics", title: "Pre-Qualification vs. Pre-Approval: What's the Difference?", read: "5 min", content: `These terms are often used interchangeably but they are not the same thing - and understanding the difference can affect how seriously sellers take your offer.\n\n**Pre-Qualification**\nPre-qualification is an informal estimate of how much you might be able to borrow based on self-reported financial information. No documents are verified. It takes minutes and gives you a rough range - but it carries little weight with sellers.\n\n**Pre-Approval**\nPre-approval is a formal process where the lender verifies your income, assets, debts, and credit score by reviewing actual documentation. The result is a conditional commitment letter stating the loan amount, rate type, and loan program you qualify for.\n\n**Why It Matters**\nIn a competitive market, sellers often won't consider offers without a pre-approval letter. Pre-approval also helps you move faster when you find the right home - sometimes closing in as little as 21 days.\n\n**What You'll Need for Pre-Approval**\n- Last 2 years of W-2s and federal tax returns\n- 30 days of recent pay stubs\n- 60 days of bank and investment account statements\n- Government-issued photo ID\n- Rental history or landlord contact information\n\nGet pre-approved before you start touring homes. It costs nothing and positions you as a serious buyer.` },
  { cat: "Credit & Financing", title: "Understanding Your Credit Score and How It Affects Your Rate", read: "7 min", content: `Your credit score is one of the most powerful numbers in your financial life. For mortgage purposes, lenders use the FICO Score model and pull reports from all three bureaus - Equifax, Experian, and TransUnion - using the middle score.\n\n**Score Ranges and What They Mean**\n- 760+: Best rates available\n- 720-759: Very good - competitive rates\n- 680-719: Good - slightly higher rates\n- 640-679: Fair - higher rates, limited programs\n- 580-639: Minimum for FHA - significantly higher rates\n- Below 580: Most conventional lenders will not approve\n\n**What Makes Up Your Score**\n- Payment history (35%): The most important factor\n- Credit utilization (30%): Keep balances below 30% of limits\n- Length of credit history (15%): Older accounts help\n- Credit mix (10%): Having different types of credit helps\n- New inquiries (10%): Minimize new applications before buying\n\n**Rate Impact Example**\nOn a $300,000 loan, the difference between a 620 and 760 credit score can be 1.5-2% in interest rate - translating to $200-$300 more per month and $75,000+ more over the life of the loan.\n\n**How to Improve Your Score**\nPay on time, pay down balances, don't open new accounts, and dispute any errors you find on your credit report.` },
  { cat: "Credit & Financing", title: "Fixed vs. Adjustable Rate Mortgages Explained", read: "6 min", content: `Choosing between a fixed and adjustable rate mortgage is one of the most important decisions in your home purchase. Here's what you need to know.\n\n**Fixed-Rate Mortgage**\nYour interest rate stays the same for the entire loan term - typically 30, 20, or 15 years. Your principal and interest payment never changes, making budgeting simple and predictable.\n\n*Best for:* Buyers who plan to stay in their home long-term, prefer payment stability, or are buying in a low-rate environment.\n\n**Adjustable-Rate Mortgage (ARM)**\nARMs start with a fixed rate for an initial period (commonly 5, 7, or 10 years), then adjust annually based on a market index. A 7/1 ARM has a fixed rate for 7 years, then adjusts each year after.\n\n*Best for:* Buyers who are confident they'll sell or refinance before the fixed period ends, or who need a lower initial rate to qualify.\n\n**ARM Caps**\nARMs have rate caps that limit how much the rate can increase at each adjustment and over the life of the loan. A 5/2/5 cap means the rate can go up 5% initially, 2% per adjustment, and 5% total.\n\n**Which Is Right for You?**\nIn most market conditions, a 30-year fixed provides the most security. Consult your mortgage advisor before choosing an ARM - the lower initial payment comes with future uncertainty.` },
  { cat: "Down Payment", title: "How to Save for a Down Payment", read: "8 min", content: `Saving for a down payment is the biggest barrier most first-time buyers face. Here's a strategic approach to getting there faster.\n\n**Know Your Target**\nUse the Down Payment Calculator to determine exactly how much you need. Don't forget closing costs (typically 2-5% of the loan amount) in addition to your down payment.\n\n**Open a Dedicated Savings Account**\nOpen a separate high-yield savings account labeled "Home Fund." This creates a psychological barrier to spending and earns more interest than a standard account.\n\n**Automate Your Savings**\nSet up an automatic transfer on payday - even $200/month adds up to $2,400 per year. Treat it like a non-negotiable bill.\n\n**Cut Strategically**\nUse the Savings Tracker to identify which expenses, when removed, have the biggest impact over 3, 6, and 12 months. Focus on recurring monthly costs - subscriptions, dining, memberships.\n\n**Explore Down Payment Assistance**\nMany buyers don't realize they may qualify for grants or forgivable loans covering part or all of their down payment. Review the Housing Assistance section of this portal.\n\n**Gift Funds**\nConventional, FHA, and many other loan types allow gift funds from family members for the down payment. Your lender will need a gift letter.\n\n**Retirement Accounts**\nFirst-time buyers may be able to withdraw up to $10,000 from an IRA without the 10% early withdrawal penalty. Consult a tax advisor before doing this.` },
  { cat: "Down Payment", title: "Down Payment Assistance Programs: A Complete Guide", read: "10 min", content: `You may not need as much saved as you think. Down payment assistance (DPA) programs can cover part - or sometimes all - of your down payment and closing costs.\n\n**Types of DPA**\n- **Grants:** Free money that doesn't need to be repaid. Typically 2-5% of the loan amount.\n- **Forgivable Second Liens:** A second mortgage with no monthly payment that is forgiven after a specified period (typically 3-5 years) if you remain in the home.\n- **Deferred Second Liens:** A second mortgage with no monthly payment, due when you sell, refinance, or pay off the first mortgage.\n- **Low-Interest Second Loans:** A second mortgage with a below-market interest rate.\n\n**Who Offers DPA?**\n- State housing finance agencies (e.g., TSAHC in Texas)\n- County and city housing programs\n- Non-profit organizations\n- Some employers (including Sinclair's Signature Benefit)\n- Federal programs (FHA, USDA, VA, HUD)\n\n**Common Requirements**\n- First-time homebuyer status (or not having owned in 3 years)\n- Income at or below area median income\n- Completion of a homebuyer education course\n- Minimum credit score (usually 620+)\n- Purchase of a primary residence\n\n**Sinclair Signature Benefit**\nAs a Sinclair member, you have access to 1% of your loan amount toward closing costs, up to $2,500. This can be combined with other DPA programs.` },
  { cat: "Closing Process", title: "What Happens at Closing: A Step-by-Step Guide", read: "9 min", content: `Closing day is the finish line. Here's exactly what to expect so there are no surprises.\n\n**Before Closing (3 Days Prior)**\nYou'll receive your Closing Disclosure (CD), which itemizes every cost and your final loan terms. Review it carefully and compare it to your Loan Estimate. Any significant changes must be explained by your lender.\n\n**What to Bring**\n- Government-issued photo ID\n- Certified or cashier's check (or proof of wire transfer) for cash to close\n- Any remaining documentation requested by your lender\n\n**Who Will Be There**\nTypically: you, the seller (sometimes separately), title company or closing attorney, your real estate agent, and occasionally your lender.\n\n**What You'll Sign**\n- Promissory Note: Your promise to repay the loan\n- Deed of Trust: Gives the lender a security interest in the property\n- Closing Disclosure: Final itemization of costs\n- Various lender and title documents\n\n**The Final Steps**\nOnce all documents are signed and funds are verified, the deed is recorded with the county. After recordation, you receive the keys.\n\n**Common Closing Delays**\n- Wire fraud (verify all wiring instructions by phone)\n- Last-minute credit issues (don't apply for new credit before closing)\n- Title issues\n- Appraisal problems\n\nPlan for the process to take 1-3 hours.` },
  { cat: "Homeownership", title: "First-Year Homeowner Checklist", read: "8 min", content: `Congratulations on your new home. Here's what to prioritize in your first 12 months.\n\n**Immediately After Closing**\n- Change all locks\n- Locate your main water shut-off valve\n- Locate your electrical panel and label all breakers\n- Set up homeowner's insurance (required before closing)\n- Forward your mail and update your address\n\n**First 30 Days**\n- Transfer all utilities into your name\n- Test all smoke and carbon monoxide detectors\n- Schedule a pest inspection if not done during purchase\n- Find a reliable plumber, electrician, and HVAC technician before you need them\n\n**First 6 Months**\n- Service your HVAC system (replace filters every 90 days)\n- Clean gutters and check the roof after the first major storm\n- Test all GFCI outlets\n- Check caulking around tubs, showers, and windows\n\n**First Year**\n- Track all home improvement receipts (they may be deductible when you sell)\n- Review your property tax assessment - errors are common\n- File for any homestead exemptions available in your area (in Texas, this can save hundreds per year)\n- Consider a home warranty for older systems and appliances\n\n**Building Equity**\nEven small extra principal payments accelerate equity. One extra payment per year on a 30-year loan shaves years off your mortgage.` },
  { cat: "Homeownership", title: "Building Home Equity: Strategies for Long-Term Wealth", read: "7 min", content: `Homeownership is a proven wealth-building tool. Here's how to accelerate equity growth.\n\n**What Is Equity?**\nEquity is the difference between your home's market value and what you owe on your mortgage. Example: a $350,000 home with a $280,000 loan balance = $70,000 in equity.\n\n**How Equity Grows**\n1. **Loan paydown:** Each mortgage payment reduces your principal balance\n2. **Appreciation:** Home values historically increase 3-5% annually\n3. **Improvements:** Strategic renovations can increase value above their cost\n4. **Down payment:** Your starting equity is the down payment you made at purchase\n\n**Strategies to Build Equity Faster**\n- Make one extra principal payment per year\n- Apply any windfalls (tax refunds, bonuses) directly to principal\n- Refinance to a shorter term when rates allow\n- Avoid cash-out refinances that reset your balance\n\n**When to Use Your Equity**\n- Home equity loans and HELOCs can fund renovations that further increase value\n- Avoid using equity for depreciating assets (cars, vacations)\n- Equity can fund a down payment on an investment property\n\n**Texas Homestead Protections**\nTexas has some of the strongest homestead protections in the country. Your primary residence is protected from most creditors and benefits from a homestead exemption that reduces your taxable value by at least $100,000 (as of 2023 legislation).` },
];

function EducationCenter({ onProgress }) {
  const [cat, setCat] = useState("All");
  const [selected, setSelected] = useState(null);
  const cats = ["All", ...new Set(ARTICLES.map(a => a.cat))];
  const filtered = cat === "All" ? ARTICLES : ARTICLES.filter(a => a.cat === cat);

  if (selected !== null) {
    const article = ARTICLES[selected];
    return (
      <div>
        <button onClick={() => setSelected(null)} style={{ background: "none", border: "none", color: C.navy, cursor: "pointer", fontSize: 14, marginBottom: 16, fontFamily: "inherit" }}>← Back to Education Center</button>
        <div style={S.card}>
          <div style={{ fontSize: 11, color: C.gold, textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: 8 }}>{article.cat}</div>
          <h2 style={{ ...S.h2, marginBottom: 8 }}>{article.title}</h2>
          <div style={{ fontSize: 13, color: C.muted, marginBottom: 24 }}>{article.read} read</div>
          <div style={{ fontSize: 15, color: "#333", lineHeight: 1.9 }}>
            {article.content.split("\n\n").map((para, i) => {
              if (para.startsWith("**") && para.endsWith("**")) {
                return <h3 key={i} style={{ color: C.navy, fontSize: 16, marginTop: 24, marginBottom: 8 }}>{para.replace(/\*\*/g, "")}</h3>;
              }
              const formatted = para.replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>");
              return <p key={i} style={{ marginBottom: 16 }} dangerouslySetInnerHTML={{ __html: formatted }} />;
            })}
          </div>
          <div style={{ marginTop: 32, borderTop: `1px solid ${C.border}`, paddingTop: 20, textAlign: "center" }}>
            <p style={{ color: C.muted, fontSize: 14, marginBottom: 16 }}>Ready to put this knowledge to work?</p>
            <a href={APP_LINK} target="_blank" rel="noreferrer" style={{ ...S.btnGold, textDecoration: "none" }}>Start Your Application →</a>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div>
      <h2 style={S.h2}>Education Center</h2>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 20 }}>
        {cats.map(c => (
          <button key={c} onClick={() => setCat(c)} style={{ padding: "6px 14px", borderRadius: 20, border: `1.5px solid ${cat === c ? C.navy : C.border}`, background: cat === c ? C.navy : "transparent", color: cat === c ? C.white : C.muted, fontSize: 12, cursor: "pointer" }}>{c}</button>
        ))}
      </div>
      <div style={S.grid(2)}>
        {filtered.map((a, i) => {
          const idx = ARTICLES.indexOf(a);
          return (
            <div key={i} onClick={() => { setSelected(idx); onProgress("Education Center"); }} style={{ ...S.card, cursor: "pointer", marginBottom: 0, transition: "box-shadow 0.15s" }}>
              <div style={{ fontSize: 11, color: C.gold, textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: 8 }}>{a.cat}</div>
              <div style={{ fontWeight: "bold", color: C.navy, fontSize: 15, lineHeight: 1.4, marginBottom: 8 }}>{a.title}</div>
              <div style={{ fontSize: 12, color: C.muted }}>{a.read} read →</div>
            </div>
          );
        })}
      </div>
    </div>
  );
}


