function ResourceLibrary({ onProgress }) {
  const [selected, setSelected] = useState(null);
  const [filter, setFilter] = useState("All");
  const types = ["All", "Guide", "Template", "Checklist", "FAQ"];
  const typeColor = { Guide: C.navy, Template: C.gold, Checklist: C.green, FAQ: C.red };
  const filtered = filter === "All" ? RESOURCES_DATA : RESOURCES_DATA.filter(r => r.type === filter);

  function download(resource) {
    onProgress("Resource Library");
    const blob = new Blob([`<html><head><meta charset="UTF-8"><style>body{font-family:Georgia,serif;padding:40px;max-width:800px;margin:0 auto;color:#0B1E3F;} h1,h2,h3{color:#0B1E3F;} h2{color:#B8871E;} table{width:100%;border-collapse:collapse;} td,th{border:1px solid #ddd;padding:8px;} .footer{margin-top:40px;font-size:12px;color:#999;border-top:1px solid #eee;padding-top:16px;}</style></head><body><img src="data:image/png;base64,${LOGO_B64}" style="height:48px;margin-bottom:16px;" /><div style="white-space:pre-wrap;font-size:14px;line-height:1.8;">${resource.content}</div><div class="footer">Sinclair LLC 2026 | ${ADVISOR.name} | NMLS #${ADVISOR.nmls} | <a href="${APP_LINK}">${APP_LINK}</a></div></body></html>`], { type: "text/html" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = `${resource.name.replace(/\s+/g, "_")}.html`; a.click();
    URL.revokeObjectURL(url);
  }

  if (selected !== null) {
    const resource = RESOURCES_DATA[selected];
    return (
      <div>
        <button onClick={() => setSelected(null)} style={{ background: "none", border: "none", color: C.navy, cursor: "pointer", fontSize: 14, marginBottom: 16, fontFamily: "inherit" }}>← Back to Resource Library</button>
        <div style={S.card}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 20 }}>
            <div>
              <span style={S.pill(typeColor[resource.type] || C.muted)}>{resource.type}</span>
              <h2 style={{ ...S.h2, marginTop: 12, marginBottom: 4 }}>{resource.name}</h2>
              <p style={{ color: C.muted, fontSize: 14, margin: 0 }}>{resource.desc}</p>
            </div>
            <button onClick={() => download(resource)} style={{ ...S.btnGold, whiteSpace: "nowrap", marginLeft: 16 }}>↓ Download</button>
          </div>
          <div style={{ background: C.offwhite, borderRadius: 6, padding: 24, fontSize: 14, lineHeight: 1.9, color: "#333", whiteSpace: "pre-wrap" }}>
            {resource.content.split("\n").map((line, i) => {
              if (line.startsWith("# ")) return <h1 key={i} style={{ color: C.navy, fontFamily: "Georgia, serif", fontSize: 22, marginBottom: 16 }}>{line.replace("# ", "")}</h1>;
              if (line.startsWith("## ")) return <h2 key={i} style={{ color: C.gold, fontSize: 17, marginTop: 24, marginBottom: 8 }}>{line.replace("## ", "")}</h2>;
              if (line.startsWith("**") && line.endsWith("**")) return <p key={i} style={{ fontWeight: "bold", color: C.navy, margin: "12px 0 4px" }}>{line.replace(/\*\*/g, "")}</p>;
              if (line.startsWith("- [ ]")) return <div key={i} style={{ display: "flex", gap: 10, margin: "6px 0" }}><input type="checkbox" /><span>{line.replace("- [ ] ", "")}</span></div>;
              if (line.startsWith("- ")) return <li key={i} style={{ margin: "4px 0", color: C.muted }}>{line.replace("- ", "")}</li>;
              if (line.startsWith("---")) return <hr key={i} style={{ border: "none", borderTop: `1px solid ${C.border}`, margin: "20px 0" }} />;
              return <p key={i} style={{ margin: "4px 0", color: line.startsWith("Q:") ? C.navy : line.startsWith("A:") ? C.muted : "inherit", fontWeight: line.startsWith("Q:") ? "bold" : "normal" }}>{line}</p>;
            })}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div>
      <h2 style={S.h2}>Resource Library</h2>
      <div style={{ display: "flex", gap: 8, marginBottom: 20 }}>
        {types.map(t => (
          <button key={t} onClick={() => setFilter(t)} style={{ padding: "6px 16px", borderRadius: 20, border: `1.5px solid ${filter === t ? C.navy : C.border}`, background: filter === t ? C.navy : "transparent", color: filter === t ? C.white : C.muted, fontSize: 13, cursor: "pointer" }}>{t}</button>
        ))}
      </div>
      {filtered.map((r, i) => {
        const idx = RESOURCES_DATA.indexOf(r);
        return (
          <div key={i} style={{ ...S.card, display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
            <div style={{ display: "flex", gap: 16, alignItems: "center", cursor: "pointer", flex: 1 }} onClick={() => setSelected(idx)}>
              <span style={{ fontSize: 24 }}>📄</span>
              <div>
                <div style={{ fontWeight: "bold", color: C.navy, fontSize: 14 }}>{r.name}</div>
                <div style={{ fontSize: 12, color: C.muted }}><span style={S.pill(typeColor[r.type] || C.muted)}>{r.type}</span><span style={{ marginLeft: 10 }}>{r.desc}</span></div>
              </div>
            </div>
            <div style={{ display: "flex", gap: 8, marginLeft: 16 }}>
              <button onClick={() => setSelected(idx)} style={{ ...S.btnPrimary, fontSize: 12, padding: "8px 14px" }}>View</button>
              <button onClick={() => download(r)} style={{ ...S.btnGold, fontSize: 12, padding: "8px 14px" }}>↓</button>
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ── SCHEDULE CONSULTATION ───────────────────────────────────
const LO_LIST = [
  { name: "Yves Ozoude", nmls: "1857419", email: "YOzoude@UHM.com", phone: "713-931-0655", company: "United Home Mortgage" },
];

function ScheduleConsultation({ onProgress }) {
  const [selectedLO, setSelectedLO] = useState(0);
  const [form, setForm] = useState({ name: "", email: "", phone: "", topic: "Getting Started", message: "", date: "" });
  const [sent, setSent] = useState(false);
  const lo = LO_LIST[selectedLO];

  function handleSubmit(e) {
    e.preventDefault();
    setSent(true);
    onProgress("Schedule Consultation");
  }

  return (
    <div>
      <h2 style={S.h2}>Schedule a Consultation</h2>

      {/* LO Selection */}
      <div style={S.card}>
        <h3 style={S.h3}>Choose Your Loan Officer</h3>
        {LO_LIST.map((l, i) => (
          <div key={i} onClick={() => setSelectedLO(i)} style={{ display: "flex", gap: 16, alignItems: "center", padding: "12px 16px", borderRadius: 6, border: `1.5px solid ${selectedLO === i ? C.navy : C.border}`, background: selectedLO === i ? "#f0f4fa" : C.white, cursor: "pointer", marginBottom: 10 }}>
            <div style={{ width: 44, height: 44, borderRadius: "50%", background: C.navy, color: C.gold, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18, fontFamily: "Georgia, serif" }}>{l.name[0]}</div>
            <div>
              <div style={{ fontWeight: "bold", color: C.navy }}>{l.name}</div>
              <div style={{ fontSize: 13, color: C.muted }}>NMLS #{l.nmls} · {l.company}</div>
              <div style={{ fontSize: 13, color: C.muted }}>{l.phone} · {l.email}</div>
            </div>
            {selectedLO === i && <span style={{ marginLeft: "auto", color: C.navy, fontSize: 18 }}>✓</span>}
          </div>
        ))}
      </div>

      {/* General Contact */}
      <div style={{ ...S.card, background: C.offwhite, marginBottom: 20 }}>
        <p style={{ fontSize: 14, color: C.muted, margin: 0 }}>Prefer to email directly? <a href={`mailto:${lo.email}`} style={{ color: C.navy, fontWeight: "bold" }}>{lo.email}</a></p>
      </div>

      {!sent ? (
        <div style={S.card}>
          <h3 style={S.h3}>Request a Consultation with {lo.name}</h3>
          <form onSubmit={handleSubmit}>
            <div style={S.grid(2)}>
              {[["Full Name","name","text","Jane Smith"],["Email","email","email","jane@email.com"],["Phone","phone","tel","(555) 000-0000"],["Preferred Date","date","date",""]].map(([l,k,t,ph]) => (
                <div key={k}><label style={S.label}>{l}</label><input style={S.input} type={t} placeholder={ph} value={form[k]} onChange={e => setForm({...form, [k]: e.target.value})} /></div>
              ))}
            </div>
            <label style={S.label}>Topic</label>
            <select style={S.input} value={form.topic} onChange={e => setForm({...form, topic: e.target.value})}>
              {["Getting Started","Pre-Approval","Down Payment Assistance","Credit Questions","Refinancing","General Questions"].map(t => <option key={t}>{t}</option>)}
            </select>
            <label style={S.label}>Message (optional)</label>
            <textarea style={{ ...S.input, height: 100, resize: "vertical" }} value={form.message} onChange={e => setForm({...form, message: e.target.value})} />
            <button type="submit" style={S.btnPrimary}>Request Consultation</button>
          </form>
        </div>
      ) : (
        <div style={{ ...S.card, textAlign: "center", padding: 40 }}>
          <div style={{ fontSize: 40, marginBottom: 12 }}>✓</div>
          <h3 style={{ color: C.green, fontSize: 18, fontWeight: "normal" }}>Request Received</h3>
          <p style={{ color: C.muted, fontSize: 14 }}>{lo.name} will contact you at <strong>{form.email}</strong> within one business day.</p>
          <p style={{ color: C.muted, fontSize: 13 }}>Or call directly: <strong>{lo.phone}</strong></p>
          <div style={{ display: "flex", gap: 12, justifyContent: "center", marginTop: 20, flexWrap: "wrap" }}>
            <a href={APP_LINK} target="_blank" rel="noreferrer" style={{ ...S.btnGold, textDecoration: "none" }}>Start Your Application While You Wait →</a>
            <button style={{ ...S.btnPrimary, background: "transparent", color: C.navy, border: `1.5px solid ${C.navy}` }} onClick={() => setSent(false)}>Schedule Another</button>
          </div>
        </div>
      )}
    </div>
  );
}


// ── MAIN APP ────────────────────────────────────────────────
const SECTIONS = [
  "Dashboard","Readiness Assessment","Budget Tool","Affordability Calculator",
  "Down Payment Calculator","Refinance Calculator","Closing Cost Calculator",
  "Cash-to-Close Calculator","Credit Planner","Savings Tracker",
  "Housing Assistance","Education Center","Resource Library","Schedule Consultation",
];

export default function SinclairDemo() {
  const [section, setSection] = useState("Dashboard");
  const [readinessScore, setReadinessScore] = useState(null);
  const [progress, setProgress] = useState({});

  function markProgress(sec) {
    setProgress(p => ({ ...p, [sec]: true }));
  }

  const sectionMap = {
    "Dashboard": <Dashboard score={readinessScore} progress={progress} setSection={setSection} />,
    "Readiness Assessment": <ReadinessAssessment onScore={setReadinessScore} onProgress={markProgress} />,
    "Budget Tool": <BudgetTool onProgress={markProgress} />,
    "Affordability Calculator": <AffordabilityCalc onProgress={markProgress} />,
    "Down Payment Calculator": <DownPaymentCalc onProgress={markProgress} />,
    "Refinance Calculator": <RefinanceCalc onProgress={markProgress} />,
    "Closing Cost Calculator": <ClosingCostCalc onProgress={markProgress} />,
    "Cash-to-Close Calculator": <CashToCloseCalc onProgress={markProgress} />,
    "Credit Planner": <CreditPlanner onProgress={markProgress} />,
    "Savings Tracker": <SavingsTracker onProgress={markProgress} />,
    "Housing Assistance": <HousingAssistance onProgress={markProgress} />,
    "Education Center": <EducationCenter onProgress={markProgress} />,
    "Resource Library": <ResourceLibrary onProgress={markProgress} />,
    "Schedule Consultation": <ScheduleConsultation onProgress={markProgress} />,
  };

  const completedCount = Object.values(progress).filter(Boolean).length;

  return (
    <div style={{ display: "flex", minHeight: "100vh", fontFamily: "-apple-system, BlinkMacSystemFont, Inter, sans-serif" }}>
      {/* Sidebar */}
      <div style={S.sidebar}>
        <div style={{ padding: "20px 20px 12px", borderBottom: "1px solid rgba(255,255,255,0.1)" }}>
          <img src={`data:image/png;base64,${LOGO_B64}`} alt="Sinclair" style={{ width: "100%", maxWidth: 160, height: "auto" }} />
        </div>
        {/* Progress */}
        <div style={{ padding: "12px 20px", borderBottom: "1px solid rgba(255,255,255,0.1)" }}>
          <div style={{ fontSize: 11, color: "rgba(255,255,255,0.5)", marginBottom: 6 }}>YOUR PROGRESS</div>
          <div style={{ background: "rgba(255,255,255,0.1)", borderRadius: 20, height: 6, overflow: "hidden" }}>
            <div style={{ width: `${(completedCount / SECTIONS.length) * 100}%`, height: "100%", background: C.gold, borderRadius: 20, transition: "width 0.4s" }} />
          </div>
          <div style={{ fontSize: 11, color: C.gold, marginTop: 4 }}>{completedCount}/{SECTIONS.length} sections</div>
        </div>
        <div style={{ flex: 1, overflowY: "auto", paddingTop: 6 }}>
          {SECTIONS.map(name => (
            <div key={name} style={{ ...S.navItem(section === name), display: "flex", alignItems: "center", justifyContent: "space-between" }} onClick={() => setSection(name)}>
              <span>{name}</span>
              {progress[name] && <span style={{ color: C.gold, fontSize: 12 }}>✓</span>}
            </div>
          ))}
        </div>
        <div style={{ padding: "16px 20px", borderTop: "1px solid rgba(255,255,255,0.1)", fontSize: 11, color: "rgba(255,255,255,0.3)", textAlign: "center" }}>
          © Sinclair LLC 2026
        </div>
      </div>

      {/* Main */}
      <div style={S.main}>
        <div style={S.demoBanner}>
          🔍 <strong>Demo Mode</strong> - All tools are fully functional. No data is saved.
          <button onClick={() => window.location.href = "/"} style={{ marginLeft: 16, background: "none", border: "1px solid #856404", borderRadius: 3, color: "#856404", fontSize: 12, padding: "2px 10px", cursor: "pointer" }}>Create Account</button>
        </div>
        <div style={S.topbar}>
          <div style={{ fontWeight: "bold", color: C.navy, fontSize: 15 }}>{section}</div>
          <button onClick={() => window.location.href = "/"} style={{ background: "none", border: `1.5px solid ${C.border}`, borderRadius: 4, padding: "6px 16px", fontSize: 13, color: C.muted, cursor: "pointer" }}>← Back to Login</button>
        </div>
        <div style={{ flex: 1, padding: "48px 52px", overflowY: "auto", maxWidth: 1100, width: "100%" }}>
          {sectionMap[section]}
        </div>
      </div>
    </div>
  );
}
